<?php
require_once __DIR__ . "/../includes/admin-check.php"; require_once __DIR__ . "/../Config/db.php"; require_once __DIR__ . "/../includes/ui.php";
function sr_admin_distance_km(float $lat1,float $lon1,float $lat2,float $lon2): float { $r=6371; $dLat=deg2rad($lat2-$lat1); $dLon=deg2rad($lon2-$lon1); $a=sin($dLat/2)**2+cos(deg2rad($lat1))*cos(deg2rad($lat2))*sin($dLon/2)**2; return $r*2*atan2(sqrt($a),sqrt(1-$a)); }
$statusFilter=trim($_GET['status']??''); $where=$statusFilter!==''?"WHERE r.status='".$conn->real_escape_string($statusFilter)."'":"";
$reports=$conn->query("SELECT r.*, u.name reporter_name, a.ambulance_name, a.status ambulance_status FROM reports r LEFT JOIN users u ON u.id=r.user_id LEFT JOIN ambulance_locations a ON a.id=r.assigned_ambulance_id $where ORDER BY FIELD(r.status,'Pending','Verified','Ambulance Sent','Resolved','Rejected'), r.priority_score DESC, r.created_at DESC");
$fleet=[]; $fleetResult=$conn->query("SELECT * FROM ambulance_locations ORDER BY id ASC"); while($row=$fleetResult->fetch_assoc()) $fleet[]=$row;
$availableFleet=array_values(array_filter($fleet,fn($a)=>($a['status']??'')==='available' && empty($a['assigned_report_id'])));
function sr_nearest_preview(array $availableFleet, array $report): ?array {
    if($report['latitude']===null || $report['longitude']===null) return null;
    $best=null; $bestD=PHP_FLOAT_MAX;
    foreach($availableFleet as $a){ $d=sr_admin_distance_km((float)$a['latitude'],(float)$a['longitude'],(float)$report['latitude'],(float)$report['longitude']); if($d<$bestD){$best=$a;$bestD=$d;} }
    return $best ? ['ambulance'=>$best,'distance'=>$bestD] : null;
}
sr_page_start('Incident Management','reports');
?>
<div class="hero-card"><span class="demo-chip">Intelligent Emergency Dispatch</span><h2>Verify an incident, then send the nearest available ambulance</h2><p>SafeRoad compares the accident GPS with all available fleet units. The closest unit is selected automatically, while busy ambulances are excluded from selection.</p><div class="toolbar" style="margin-top:18px"><a class="btn light" href="?">All</a><a class="btn light" href="?status=Pending">Pending</a><a class="btn light" href="?status=Ambulance%20Sent">Ambulance Sent</a><a class="btn light" href="?status=Resolved">Resolved</a><a class="btn warning" href="../actions/reset-demo.php" onclick="return confirmAction('Reset demo data and seed one clean incident?')">Reset + Seed Demo</a><a class="btn light" href="map.php">Open Live Map</a></div></div>

<div class="card fleet-overview-card" style="margin-top:18px"><div class="section-heading"><div><span class="section-eyebrow">LIVE FLEET</span><h2>4-Ambulance Coverage</h2></div><span class="fleet-count"><?php echo count($availableFleet); ?>/<?php echo count($fleet); ?> available</span></div><div class="grid grid-4 fleet-grid"><?php foreach($fleet as $a): ?><div class="fleet-card <?php echo ($a['status']??'')==='available'?'fleet-available':'fleet-busy'; ?>"><div class="fleet-card-top"><span class="fleet-vehicle">🚑</span><div><h3><?php echo htmlspecialchars($a['ambulance_name']); ?></h3><span class="mini"><?php echo htmlspecialchars($a['driver_name'] ?? 'Driver'); ?></span></div><?php echo sr_badge($a['status']); ?></div><div class="fleet-meta"><span>📞 <?php echo htmlspecialchars($a['phone'] ?? 'N/A'); ?></span><span>⚡ <?php echo (int)$a['speed_kmh']; ?> km/h</span><span>📍 <?php echo number_format((float)$a['latitude'],4); ?>, <?php echo number_format((float)$a['longitude'],4); ?></span></div><p class="mini fleet-mission"><?php echo htmlspecialchars($a['current_mission'] ?: 'Ready for nearest-incident dispatch'); ?></p></div><?php endforeach; ?></div></div>

<div class="card" style="margin-top:18px"><div class="section-heading"><div><span class="section-eyebrow">CONTROL QUEUE</span><h2>Incident Queue</h2></div><span class="mini">Nearest unit is recalculated from current fleet GPS</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Incident</th><th>AI Triage</th><th>Priority</th><th>Nearest Available Unit</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($reports && $reports->num_rows): while($r=$reports->fetch_assoc()): $near=sr_nearest_preview($availableFleet,$r); ?><tr><td>#<?php echo (int)$r['id']; ?></td><td><strong><?php echo htmlspecialchars($r['title']); ?></strong><br><span class="mini"><?php echo htmlspecialchars($r['location']); ?><br>GPS: <?php echo $r['latitude']!==null?number_format((float)$r['latitude'],5):'N/A'; ?>, <?php echo $r['longitude']!==null?number_format((float)$r['longitude'],5):'N/A'; ?></span></td><td><?php echo sr_badge($r['ai_verdict']); ?><br><div class="progress" style="margin-top:8px"><span style="width:<?php echo (int)$r['ai_score']; ?>%"></span></div><span class="mini"><?php echo (int)$r['ai_score']; ?>/100</span></td><td><strong><?php echo (int)$r['priority_score']; ?>/100</strong><br><?php echo sr_badge(sr_priority_label((int)$r['priority_score'])); ?></td><td><?php if(!empty($r['assigned_ambulance_id'])): ?><div class="nearest-unit assigned"><strong>🚑 <?php echo htmlspecialchars($r['ambulance_name'] ?: 'Assigned unit'); ?></strong><span>Already assigned</span></div><?php elseif($near): ?><div class="nearest-unit"><strong>🚑 <?php echo htmlspecialchars($near['ambulance']['ambulance_name']); ?></strong><span><?php echo number_format($near['distance'],2); ?> km away · GPS nearest</span></div><?php else: ?><span class="mini">No available unit / GPS missing</span><?php endif; ?></td><td><?php echo sr_badge($r['status']); ?><br><span class="mini"><?php echo htmlspecialchars($r['ambulance_name'] ?? 'No ambulance'); ?></span></td><td><div class="toolbar"><form action="../actions/ai-video-check.php" method="POST"><input type="hidden" name="report_id" value="<?php echo (int)$r['id']; ?>"><button class="btn small" type="submit">🤖 Analyze</button></form><form action="../actions/update-status.php" method="POST"><input type="hidden" name="report_id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="status" value="Verified"><button class="btn small ok" type="submit">✓ Verify</button></form><?php if(($r['status']??'')==='Verified'): ?><form action="../actions/dispatch-ambulance.php" method="POST"><input type="hidden" name="report_id" value="<?php echo (int)$r['id']; ?>"><button class="btn small danger" type="submit" title="Automatically sends the nearest available ambulance">🚑 Dispatch Nearest</button></form><?php else: ?><button class="btn small light" type="button" disabled title="Verify before dispatch">🚑 Dispatch Nearest</button><?php endif; ?><a class="btn small light" href="report-details.php?id=<?php echo (int)$r['id']; ?>">Details</a></div></td></tr><?php endwhile; else: ?><tr><td colspan="7"><div class="empty-state">No reports yet. Use Reset + Seed Demo or submit an accident from any GPS point on the citizen map.</div></td></tr><?php endif; ?></tbody></table></div></div>
<?php sr_page_end(); ?>
